@import url('https://fonts.googleapis.com/css2?family=Abril+Fatface&family=Outfit:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap');

/* Maximalism — clashing saturated colors, mixed display fonts, dense layered patterns */
.theme-maximalism {
  --bg: oklch(0.55 0.24 330);
  --surface: oklch(0.95 0.14 95);
  --surface-2: oklch(0.72 0.2 200);
  --fg: oklch(0.180 0.020 320);
  --fg-muted: oklch(0.27 0.08 320);
  --accent: oklch(0.62 0.26 25);
  --accent-fg: oklch(0.98 0.05 95);
  --accent-2: oklch(0.68 0.21 155);
  --line: oklch(0.2 0.08 320);
  --success: oklch(0.68 0.21 155);
  --warning: oklch(0.82 0.2 85);
  --danger: oklch(0.58 0.26 20);

  --radius: 1.25rem;
  --radius-sm: 0.5rem;
  --radius-lg: 2rem 0.25rem 2rem 0.25rem;
  --radius-pill: 999px;

  --shadow-1: 4px 4px 0 0 var(--line);
  --shadow-2: 8px 8px 0 0 oklch(0.68 0.21 155);
  --shadow-3: 12px 12px 0 0 oklch(0.72 0.2 200), 12px 12px 0 3px var(--line);
  --glow: 0 0 0 4px oklch(0.95 0.14 95);

  --border-width: 3px;
  --blur-amount: 0px;

  --font-display: "Abril Fatface", "Playfair Display", serif;
  --font-body: "Outfit", "Segoe UI", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;

  --tracking-display: -0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.12em;

  background-color: var(--bg);
  background-image:
    repeating-linear-gradient(45deg, oklch(0.82 0.2 85 / 0.35) 0 14px, transparent 14px 28px),
    repeating-linear-gradient(-45deg, oklch(0.72 0.2 200 / 0.3) 0 18px, transparent 18px 36px),
    radial-gradient(circle at 20% 20%, oklch(0.68 0.21 155 / 0.45), transparent 45%),
    radial-gradient(circle at 85% 70%, oklch(0.62 0.26 25 / 0.45), transparent 45%);
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-maximalism h1,
.theme-maximalism h2 {
  font-family: var(--font-display);
  font-weight: 400;
  letter-spacing: var(--tracking-display);
}

.theme-maximalism h3,
.theme-maximalism h4 {
  font-family: "Bebas Neue", "Outfit", sans-serif;
  letter-spacing: 0.05em;
}

/* signature */
.theme-maximalism h1 { text-shadow: 3px 3px 0 var(--accent), 6px 6px 0 var(--accent-2); }
.theme-maximalism button { background-image: linear-gradient(95deg, var(--accent), var(--accent-2)); border-color: transparent; }
.theme-maximalism { background-image: repeating-conic-gradient(from 40deg, oklch(0.9 0.1 340 / 4%) 0 12deg, transparent 12deg 24deg); }
.theme-maximalism h2 { text-shadow: none; }
.theme-maximalism p, .theme-maximalism li, .theme-maximalism td { text-shadow: none; }

/* depth */
.theme-maximalism thead th { background-image: linear-gradient(95deg, var(--accent), var(--accent-2)); color: var(--accent-fg); text-transform: uppercase; letter-spacing: 0.1em; border-bottom: 3px solid var(--line); }
.theme-maximalism td { border-bottom: 2px dashed var(--line); }
.theme-maximalism tbody tr:nth-child(even) td { background: oklch(0.95 0.14 95 / 55%); }
.theme-maximalism input, .theme-maximalism textarea, .theme-maximalism select { border: 3px solid var(--line); background: var(--surface); }
.theme-maximalism input:focus-visible, .theme-maximalism textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 4px oklch(0.72 0.2 200 / 60%), 6px 6px 0 var(--accent-2); }
.theme-maximalism kbd { font-family: var(--font-mono); background: var(--fg); color: var(--surface); padding: 0.15em 0.5em; border-radius: 0.5rem 0.1rem 0.5rem 0.1rem; box-shadow: 2px 2px 0 var(--accent); }
.theme-maximalism a { color: var(--accent); font-weight: 700; text-decoration: underline wavy var(--accent-2) 2px; text-underline-offset: 4px; }
.theme-maximalism a:hover { color: var(--accent-2); text-decoration-color: var(--accent); }
.theme-maximalism ::selection { background: var(--accent-2); color: var(--fg); }
.theme-maximalism ::-webkit-scrollbar { width: 14px; }
.theme-maximalism ::-webkit-scrollbar-track { background: var(--surface); border: 2px solid var(--line); }
.theme-maximalism ::-webkit-scrollbar-thumb { background-image: linear-gradient(180deg, var(--accent), var(--accent-2), var(--warning)); border: 2px solid var(--line); border-radius: 999px; }
.theme-maximalism .label-caps { background: var(--fg); color: var(--surface); padding: 0.1em 0.6em; border-radius: 999px; }
.theme-maximalism .themed-border { border: 3px solid var(--line); border-radius: var(--radius-lg); box-shadow: 6px 6px 0 var(--accent-2); }
.theme-maximalism blockquote { border-left: 8px double var(--accent); font-family: var(--font-display); }

/* alt mode: velvet-lounge maximalism — dark but still loud, patterns stay */
.theme-maximalism.alt-mode {
  --bg: oklch(0.22 0.09 330);
  --surface: oklch(0.28 0.08 320);
  --surface-2: oklch(0.32 0.1 200);
  --fg: oklch(0.96 0.03 95);
  --fg-muted: oklch(0.8 0.05 95);
  --accent: oklch(0.680 0.220 25.0);
  --accent-2: oklch(0.78 0.18 155);
  --line: oklch(0.92 0.05 95);
  --shadow-1: 4px 4px 0 0 oklch(0.1 0.05 330);
  --shadow-2: 8px 8px 0 0 oklch(0.78 0.18 155 / 70%);
  --shadow-3: 12px 12px 0 0 oklch(0.32 0.1 200), 12px 12px 0 3px oklch(0.1 0.05 330);
  background-image:
    repeating-conic-gradient(from 40deg, oklch(0.9 0.1 340 / 5%) 0 12deg, transparent 12deg 24deg),
    radial-gradient(circle at 20% 20%, oklch(0.5 0.18 155 / 35%), transparent 45%),
    radial-gradient(circle at 85% 70%, oklch(0.45 0.2 25 / 35%), transparent 45%);
  background-attachment: fixed;
}
.theme-maximalism.alt-mode tbody tr:nth-child(even) td { background: oklch(0.32 0.1 200 / 35%); }
.theme-maximalism.alt-mode ::selection { background: var(--accent); color: var(--accent-fg); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
